description:
The [current code](https://github.com/rstudio/thematic/blob/main/R/gfonts.R#L48-L53)

```r
font_file <- function(variant) {
  dir(
    cache_dir, full.names = TRUE,
    pattern = paste0(variant, "\\.ttf$")
  )
}
```


will match both `italic.ttf` and `bolditalic.ttf` if `variant` is `"italic"`, thus passing a length-two vector to `systemfonts::register_font()` or `sysfonts::font_add()`. The fix is also simple:

```r
font_file <- function(variant) {
  dir(
    cache_dir, full.names = TRUE,
    pattern = paste0("^", variant, "\\.ttf$")
  )
}
```

This is the code that checks whether a font is available:
https://github.com/rstudio/thematic/blob/21256e257aff9d435dd1ad3606bea75a81c22574/R/hooks.R#L161-L180

However, it may not give an accurate answer, because R can render graphics asynchronously. For example, in a new R session in the terminal, run this code two times:

```R
tryCatch({
    plot(1, family = "Righteous")
  },
  warning = function(e) {
    message("Caught a warning")
  }
)
```

This is the result:

```
> tryCatch({
+     plot(1, family = "Righteous")
+   },
+   warning = function(e) {
+     message("Caught a warning")
+   }
+ )
> 
There were 36 warnings (use warnings() to see them)
> tryCatch({
+     plot(1, family = "Righteous")
+   },
+   warning = function(e) {
+     message("Caught a warning")
+   }
+ )
Caught a warning
```

The first time, the warnings are **not** caught, but the second time, they are caught. (The logic here is roughly the same as the logic used in thematic.)


For testing, here's an example using grid which does the same thing:

```R
library(grid)
tryCatch({
    grid.newpage()
    grid.text("hello world", 0.5, 0.5, gp=gpar(fontsize=40, fontfamily = "Righteous"))
  },
  warning = function(e) {
    message("got warning")
  }
)
```

Notice how neither of these plots have the right colors (if I run this in RStudio, the plots actually match my RStudio theme). Interestingly, if we set `thematic_shiny(bg = "red", fg = "blue", font="auto")` (instead of `thematic_shiny(font="auto")`), you get what you'd expect

```r
library(shiny)
library(promises)
library(thematic)

thematic_shiny(font="auto")

ui <- fluidPage(
  tags$head(
    tags$link(href="https://fonts.googleapis.com/css?family=Patrick Hand", rel="stylesheet"),
    tags$style(HTML("body{background-color:#F0FFF0; color:#8B008B; font-family: Patrick Hand}")),
    tags$style(HTML("a{color:#008000}"))
  ),
  h1("Caching async plots/keys"),
  hr(),
  fluidRow(
    column(6,
           h4("Sync base plot, Async cache key"),
           plotOutput("plotNY")
    ),
    column(6,
           h4("Async base plot, async cache key"),
           plotOutput("plotYY")
    )
  )
)

server <- function(input, output, session) {
  syncPlot <- function() {
    plot(cars)
  }
  asyncPlot <- function() {
    promise_resolve(TRUE) %...>% {
      syncPlot()
    }
  }
  syncKey <- function() {
    Sys.time()
  }
  asyncKey <- function() {
    promise_resolve(syncKey())
  }
  output$plotNY <- renderCachedPlot({
    syncPlot()
  }, cacheKeyExpr = asyncKey())

  output$plotYY <- renderCachedPlot({
    asyncPlot()
  }, cacheKeyExpr = asyncKey())
}

shinyApp(ui, server)
```

Run the following example on RStudio Server Pro

```
library(shiny)
library(thematic)

theme_base <- thematic_theme("black", "white", accent = "purple")
theme_ggplot <- thematic_theme("black", "white", accent = "red")
theme_lattice <- thematic_theme("black", "white", accent = "orange")

ui <- fluidPage(
  plotOutput("base"),
  plotOutput("ggplot"),
  plotOutput("lattice")
)

server <- function(input, output, session) {
  
  output$base <- renderPlot({
    thematic_with_theme(theme_base, {
      plot(1:10, 1:10, col = thematic_get_option("accent"))
    })
  })
  
  output$ggplot <- renderPlot({
    thematic_with_theme(theme_ggplot, {
      ggplot2::qplot(1:10, 1:10, color = 1:10)
    })
  })
  
  output$lattice <- renderPlot({
    thematic_with_theme(theme_lattice, {
      lattice::show.settings()
    })
  })
  
}

shinyApp(ui, server)
```

Notice that base graph is not displayed as expected.
<img width="1560" alt="base_graph_colorado" src="https://user-images.githubusercontent.com/5369655/88934246-3d31e080-d235-11ea-85ff-afbda81ac64b.png">

Notice how the plotly graph gets printed after exiting the following shiny app: 

```r
library(plotly)
library(thematic)
library(shiny)

ui <- fluidPage(
  tags$head(
    tags$style(HTML("body{background-color:black; color:white}")),
    tags$style(HTML("a{color:#008000}"))
  ),
  plotlyOutput("ggplot")
)
server <- function(input, output) {
  output$ggplot <- renderPlotly({
    thematic_with_theme(
      thematic_theme(),
      ggplotly(qplot(1:15, 1:15, color = 1:15))
    )
  })
}
shinyApp(ui, server)
```

To make it easier to restore the old theme (and, if there was no old theme, disable). Something like:

```r
thematic_set <- function(theme) {
  if (!length(theme)) {
    return(thematic_off())
  }
  do.call(thematic_on, theme)
}
```

Then, it'll be easier to cleanup after yourself:

```r
old_theme <- thematic_on(...)
on.exit(thematic_set(old_theme))
```
